content:
:root {
  --color-bg: #f8fafc;
  --color-surface: #ffffff;
  --color-surface-hover: #f1f5f9;
  --color-surface-muted: #f1f5f9;
  --color-border: #e2e8f0;
  --color-border-subtle: #edf2f7;

  --color-text-main: #0f172a;
  --color-text-secondary: #475569;
  --color-text-muted: #94a3b8;

  --color-primary: #2563eb;
  --color-primary-dark: #1d4ed8;
  --color-primary-light: #eff6ff;
  --color-primary-border: #bfdbfe;

  --color-success: #059669;
  --color-success-bg: #ecfdf5;
  --color-success-border: #a7f3d0;

  --color-danger: #dc2626;
  --color-danger-bg: #fef2f2;
  --color-danger-border: #fecaca;

  --color-banner-start: #1e293b;
  --color-banner-end: #0f172a;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px 0 rgba(15, 23, 42, 0.05);
  --shadow-card: 0 1px 3px 0 rgba(15, 23, 42, 0.06), 0 1px 2px -1px rgba(15, 23, 42, 0.06);
  --shadow-elevated: 0 4px 6px -1px rgba(15, 23, 42, 0.07), 0 2px 4px -2px rgba(15, 23, 42, 0.05);

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Hiragino Sans', 'Noto Sans JP', sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--color-bg);
  color: var(--color-text-main);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  line-height: 1.5;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

button:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* ダッシュボードレイアウト */
.dashboard-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 20px 48px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ヘッダー */
.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 16px;
}

.header-title-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.dashboard-title {
  font-size: 1.625rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text-main);
}

.dashboard-subtitle {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
}

/* サマリーバナー */
.summary-banner {
  background: linear-gradient(135deg, var(--color-banner-start) 0%, var(--color-banner-end) 100%);
  color: #ffffff;
  border-radius: var(--radius-lg);
  padding: 16px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  box-shadow: var(--shadow-elevated);
}

.summary-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.summary-item-label {
  font-size: 0.875rem;
  opacity: 0.85;
}

.summary-item-value {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

/* 期間切り替えフィルター */
.filter-group {
  display: inline-flex;
  background-color: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  padding: 4px;
  gap: 4px;
}

.filter-btn {
  padding: 6px 16px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-full);
  transition: all 0.18s ease-in-out;
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.filter-btn:hover {
  color: var(--color-primary-dark);
  background-color: var(--color-primary-light);
}

.filter-btn:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 1px;
}

.filter-btn-active {
  background-color: var(--color-surface);
  color: var(--color-primary);
  border: 1px solid var(--color-primary-border);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

.filter-btn-active:hover {
  background-color: var(--color-surface);
  color: var(--color-primary-dark);
}

/* KPIカードグリッド */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 16px;
}

.kpi-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 20px 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: var(--shadow-card);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  min-height: 128px;
}

.kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-elevated);
}

.kpi-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-secondary);
  margin-bottom: 10px;
}

.kpi-value-group {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
}

.kpi-value {
  font-size: 1.875rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
}

.kpi-unit {
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  margin-left: 4px;
}

.kpi-badge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 0.8125rem;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: var(--radius-full);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.kpi-badge-up {
  color: var(--color-success);
  background-color: var(--color-success-bg);
  border: 1px solid var(--color-success-border);
}

.kpi-badge-down {
  color: var(--color-danger);
  background-color: var(--color-danger-bg);
  border: 1px solid var(--color-danger-border);
}

/* グラフセクション */
.charts-container {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.chart-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-card);
}

.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 24px;
}

.chart-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.metric-tabs {
  display: flex;
  background-color: var(--color-surface-muted);
  border-radius: var(--radius-md);
  padding: 3px;
  gap: 2px;
}

.metric-tab {
  padding: 6px 14px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: all 0.15s ease;
  min-height: 32px;
}

.metric-tab:hover {
  color: var(--color-primary-dark);
}

.metric-tab:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 1px;
}

.metric-tab-active {
  background-color: var(--color-surface);
  color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

/* データテーブル */
.table-container {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.data-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  text-align: left;
  font-size: 0.875rem;
}

.data-table th,
.data-table td {
  padding: 14px 18px;
  border-bottom: 1px solid var(--color-border);
  white-space: nowrap;
}

.data-table th {
  background-color: var(--color-bg);
  color: var(--color-text-secondary);
  font-weight: 600;
  font-size: 0.8125rem;
  letter-spacing: 0.02em;
}

.data-table th:first-child {
  border-top-left-radius: calc(var(--radius-lg) - 1px);
}

.data-table th:last-child {
  border-top-right-radius: calc(var(--radius-lg) - 1px);
}

.data-table tbody tr {
  transition: background-color 0.15s ease;
}

.data-table tbody tr:hover {
  background-color: var(--color-surface-hover);
}

.data-table tbody tr:last-child td {
  border-bottom: none;
}

.data-table tbody tr:last-child td:first-child {
  border-bottom-left-radius: calc(var(--radius-lg) - 1px);
}

.data-table tbody tr:last-child td:last-child {
  border-bottom-right-radius: calc(var(--radius-lg) - 1px);
}

.table-cell-month {
  font-weight: 600;
}

.table-cell-empty {
  color: var(--color-text-muted);
}

.text-right {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.text-center {
  text-align: center;
}

/* レスポンシブ調整 */
@media (max-width: 768px) {
  .dashboard-container {
    padding: 16px 12px 32px;
    gap: 16px;
  }

  .dashboard-header {
    flex-direction: column;
    align-items: stretch;
  }

  .filter-group {
    width: 100%;
    justify-content: stretch;
  }

  .filter-btn {
    flex: 1;
  }

  .chart-card {
    padding: 16px;
  }

  .chart-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .metric-tabs {
    width: 100%;
    overflow-x: auto;
  }

  .metric-tab {
    flex: 1;
    text-align: center;
    padding: 6px 8px;
  }

  .kpi-value {
    font-size: 1.5rem;
  }
}

export interface MonthlyData {
  month: string;
  revenue: number;
  customers: number;
  averageSpend: number;
}

export interface KpiSummary {
  id: string;
  title: string;
  value: string;
  diff: number;
  isIncrease: boolean;
  unit: string;
}

export interface TotalSummary {
  revenue: number;
  customers: number;
  averageSpend: number;
}

export type PeriodFilter = 'all' | '6m' | '3m';

export type MetricType = 'all' | 'revenue' | 'customers' | 'averageSpend';

export interface KpiCardProps {
  summary: KpiSummary;
}

export interface ChartSectionProps {
  data: MonthlyData[];
  activeMetric: MetricType;
  onMetricChange: (metric: MetricType) => void;
}

import { MonthlyData, PeriodFilter } from './types';

export const monthlySalesData: MonthlyData[] = [
  { month: '1月', revenue: 3250000, customers: 1250, averageSpend: 2600 },
  { month: '2月', revenue: 2980000, customers: 1150, averageSpend: 2591 },
  { month: '3月', revenue: 3680000, customers: 1380, averageSpend: 2667 },
