export const filterDataByPeriod = (
  data: MonthlyData[],
  period: PeriodFilter
): MonthlyData[] => {
  if (!Array.isArray(data) || data.length === 0) {
    return [];
  }

  const safeData = [...data];

  switch (period) {
    case '3m':
      return safeData.slice(-3);
    case '6m':
      return safeData.slice(-6);
    case 'all':
    default:
      return safeData;
  }
};

export const formatNumber = (val: number): string => {
  if (typeof val !== 'number' || Number.isNaN(val)) {
    return '0';
  }
  return new Intl.NumberFormat('ja-JP').format(Math.round(val));
};

export interface CurrencyFormatOptions {
  withSymbol?: boolean;
}

export const formatCurrency = (
  val: number,
  options?: CurrencyFormatOptions
): string => {
  const formatted = formatNumber(val);
  const withSymbol = options?.withSymbol ?? true;
  return withSymbol ? `¥${formatted}` : formatted;
};

export const formatCount = (val: number, unit?: string): string => {
  const formatted = formatNumber(val);
  return unit ? `${formatted}${unit}` : formatted;
};

import { KpiCardProps } from '../types';

const KpiCard = ({ summary }: KpiCardProps) => {
  const {
    title = '',
    value = '',
    diff = 0,
    isIncrease = true,
    unit = '',
  } = summary ?? {};

  // valueに既に通貨記号（¥）が含まれていてunitが「円」の場合は二重表示を防ぐ
  const shouldShowUnit = Boolean(
    unit && !(value.includes('¥') && unit === '円')
  );

  const formattedDiff = typeof diff === 'number' && !Number.isNaN(diff)
    ? diff.toFixed(1)
    : '0.0';

  return (
    <div className="kpi-card">
      <div className="kpi-title">{title}</div>
      <div className="kpi-value-group">
        <div>
          <span className="kpi-value">{value}</span>
          {shouldShowUnit && <span className="kpi-unit">{unit}</span>}
        </div>
        <div
          className={`kpi-badge ${isIncrease ? 'kpi-badge-up' : 'kpi-badge-down'}`}
          aria-label={`前月比 ${formattedDiff}% ${isIncrease ? '増加' : '減少'}`}
        >
          <span aria-hidden="true">{isIncrease ? '▲ +' : '▼ '}</span>
          <span aria-hidden="true">{formattedDiff}%</span>
        </div>
      </div>
    </div>
  );
};

export default KpiCard;

import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  CartesianGrid,
} from 'recharts';
import { ChartSectionProps, MetricType } from '../types';
import { formatCurrency, formatCount } from '../mockData';

const CHART_COLORS = {
  revenue: '#2563eb',
  customers: '#059669',
  averageSpend: '#d97706',
  grid: '#edf2f7',
  axis: '#94a3b8',
  tick: '#475569',
  cardBg: '#ffffff',
  border: '#e2e8f0',
  title: '#0f172a',
} as const;

const metricOptions: Array<{
  key: MetricType;
  label: string;
}> = [
  { key: 'all', label: '全体推移（複合）' },
  { key: 'revenue', label: '売上のみ' },
  { key: 'customers', label: '客数のみ' },
  { key: 'averageSpend', label: '客単価のみ' },
];

const ChartSection = ({
  data = [],
  activeMetric = 'all',
  onMetricChange,
}: ChartSectionProps) => {
  const formatYAxisRevenue = (val: number) => {
    return `${(val / 10000).toLocaleString('ja-JP')}万円`;
  };

  const formatYAxisCustomers = (val: number) => {
    return `${val.toLocaleString('ja-JP')}人`;
  };

  const formatYAxisSpend = (val: number) => {
    return `¥${val.toLocaleString('ja-JP')}`;
  };

  return (
    <div className="chart-card">
      <div className="chart-header">
        <h2 className="chart-title">月次パフォーマンス推移</h2>
        <div
          className="metric-tabs"
          role="tablist"
          aria-label="表示メトリクス切り替え"
        >
          {metricOptions.map((opt) => (
            <button
              key={opt.key}
              id={`tab-${opt.key}`}
              type="button"
              role="tab"
              aria-selected={activeMetric === opt.key}
              aria-controls="chart-panel"
              className={`metric-tab ${activeMetric === opt.key ? 'metric-tab-active' : ''}`}
              onClick={() => onMetricChange(opt.key)}
            >
              {opt.label}
            </button>
          ))}
        </div>
      </div>

      <div
        id="chart-panel"
        role="tabpanel"
        aria-labelledby={`tab-${activeMetric}`}
        style={{ width: '100%', height: 380 }}
      >
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart
            data={data}
            margin={{ top: 16, right: 24, left: 16, bottom: 8 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke={CHART_COLORS.grid} vertical={false} />
            <XAxis
              dataKey="month"
              stroke={CHART_COLORS.axis}
              tick={{ fill: CHART_COLORS.tick, fontSize: 12 }}
              tickLine={false}
            />

            {/* 左Y軸: 売上または単一メトリクス用 */}
            {(activeMetric === 'all' || activeMetric === 'revenue') && (
              <YAxis
                yAxisId="revenue"
                orientation="left"
                stroke={CHART_COLORS.revenue}
                tick={{ fill: CHART_COLORS.tick, fontSize: 12 }}
                tickFormatter={formatYAxisRevenue}
                tickLine={false}
                axisLine={false}
              />
            )}

            {activeMetric === 'customers' && (
              <YAxis
                yAxisId="customers"
                orientation="left"
                stroke={CHART_COLORS.customers}
                tick={{ fill: CHART_COLORS.tick, fontSize: 12 }}
                tickFormatter={formatYAxisCustomers}
                tickLine={false}
                axisLine={false}
              />
            )}

            {activeMetric === 'averageSpend' && (
              <YAxis
                yAxisId="spend"
                orientation="left"
                stroke={CHART_COLORS.averageSpend}
                tick={{ fill: CHART_COLORS.tick, fontSize: 12 }}
                tickFormatter={formatYAxisSpend}
                tickLine={false}
                axisLine={false}
                domain={['auto', 'auto']}
              />
            )}

            {/* 右Y軸: 全体推移表示時の客数 */}
            {activeMetric === 'all' && (
              <YAxis
                yAxisId="customers"
                orientation="right"
                stroke={CHART_COLORS.customers}
                tick={{ fill: CHART_COLORS.tick, fontSize: 12 }}
                tickFormatter={formatYAxisCustomers}
                tickLine={false}
                axisLine={false}
              />
            )}

            <Tooltip
              contentStyle={{
                backgroundColor: CHART_COLORS.cardBg,
                border: `1px solid ${CHART_COLORS.border}`,
                borderRadius: '8px',
                boxShadow: '0 4px 6px -1px rgba(15, 23, 42, 0.08)',
                fontSize: '12px',
              }}
              formatter={(value?: number | string | null, name?: string) => {
                const numericValue = typeof value === 'number' ? value : 0;
                if (!value && value !== 0) {
                  return ['-', name ?? ''];
                }
                if (name === '売上') return [`¥${formatCurrency(numericValue)}`, name];
                if (name === '客数') return [`${formatCount(numericValue)}人`, name];
                if (name === '客単価') return [`¥${formatCurrency(numericValue)}`, name];
                return [value, name ?? ''];
              }}
              labelStyle={{ fontWeight: 600, color: CHART_COLORS.title, marginBottom: '4px' }}
            />
            <Legend
              wrapperStyle={{ paddingTop: '16px', fontSize: '13px' }}
            />

            {/* 売上棒グラフ */}
            {(activeMetric === 'all' || activeMetric === 'revenue') && (
              <Bar
                yAxisId="revenue"
                dataKey="revenue"
                name="売上"
                fill={CHART_COLORS.revenue}
                radius={[4, 4, 0, 0]}
                maxBarSize={48}
              />
            )}

            {/* 客数グラフ: all時は折れ線、単体時は棒 */}
            {activeMetric === 'all' && (
              <Line
                yAxisId="customers"
                type="monotone"
                dataKey="customers"
                name="客数"
                stroke={CHART_COLORS.customers}
                strokeWidth={3}
                dot={{ r: 4, fill: CHART_COLORS.customers, strokeWidth: 2, stroke: '#ffffff' }}
                activeDot={{ r: 6 }}
              />
            )}

            {activeMetric === 'customers' && (
              <Bar
                yAxisId="customers"
                dataKey="customers"
                name="客数"
                fill={CHART_COLORS.customers}
                radius={[4, 4, 0, 0]}
                maxBarSize={48}
              />
            )}

            {/* 客単価グラフ */}
            {activeMetric === 'averageSpend' && (
              <Line
                yAxisId="spend"
                type="monotone"
                dataKey="averageSpend"
                name="客単価"
                stroke={CHART_COLORS.averageSpend}
                strokeWidth={3}
                dot={{ r: 4, fill: CHART_COLORS.averageSpend, strokeWidth: 2, stroke: '#ffffff' }}
                activeDot={{ r: 6 }}
              />
            )}
          </ComposedChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default ChartSection;

import { useState, useMemo } from 'react';
import { PeriodFilter, MetricType, KpiSummary, TotalSummary } from './types';
import {
  monthlySalesData,
  filterDataByPeriod,
  formatCurrency,
  formatCount,
} from './mockData';
import KpiCard from './components/KpiCard';
import ChartSection from './components/ChartSection';

const App = () => {
  const [period, setPeriod] = useState<PeriodFilter>('all');
  const [activeMetric, setActiveMetric] = useState<MetricType>('all');

  const filteredData = useMemo(() => {
    return filterDataByPeriod(monthlySalesData, period);
  }, [period]);

  const kpiSummaries = useMemo<KpiSummary[]>(() => {
    if (filteredData.length === 0) return [];

    const currentMonth = filteredData[filteredData.length - 1];
    const prevMonth =
      filteredData.length > 1
        ? filteredData[filteredData.length - 2]
        : currentMonth;

    const calcDiff = (curr: number, prev: number) => {
      if (prev === 0) return { diff: 0, isIncrease: true };
      const change = ((curr - prev) / prev) * 100;
      return {
        diff: Math.abs(change),
        isIncrease: change >= 0,
      };
    };

    const revDiff = calcDiff(currentMonth.revenue, prevMonth.revenue);
    const custDiff = calcDiff(currentMonth.customers, prevMonth.customers);
    const spendDiff = calcDiff(currentMonth.averageSpend, prevMonth.averageSpend);

    return [
      {
        id: 'kpi-revenue',
        title: '直近月 売上',
        value: `¥${formatCurrency(currentMonth.revenue)}`,
        diff: revDiff.diff,
        isIncrease: revDiff.isIncrease,
        unit: '円',
      },
      {
        id: 'kpi-customers',
        title: '直近月 客数',
        value: formatCount(currentMonth.customers),
        diff: custDiff.diff,
        isIncrease: custDiff.isIncrease,
        unit: '人',
      },
      {
        id: 'kpi-averageSpend',
        title: '直近月 平均客単価',
        value: `¥${formatCurrency(currentMonth.averageSpend)}`,
        diff: spendDiff.diff,
        isIncrease: spendDiff.isIncrease,
        unit: '円',
      },
    ];
  }, [filteredData]);

  const totals = useMemo<TotalSummary>(() => {
    const totalRev = filteredData.reduce((acc, cur) => acc + cur.revenue, 0);
    const totalCust = filteredData.reduce((acc, cur) => acc + cur.customers, 0);
    const avgSpend = totalCust > 0 ? Math.round(totalRev / totalCust) : 0;
    return {
      revenue: totalRev,
      customers: totalCust,
      averageSpend: avgSpend,
    };
  }, [filteredData]);

  return (
    <div className="dashboard-container">
      {/* ヘッダーエリア */}
      <header className="dashboard-header">
        <div className="header-title-group">
          <h1 className="dashboard-title">売上分析ダッシュボード</h1>
          <p className="dashboard-subtitle">
            月次売上・客数・客単価の統合パフォーマンス管理
          </p>
        </div>
        <div className="filter-group" role="toolbar" aria-label="集計期間切り替え">
          <button
            type="button"
            className={`filter-btn ${period === 'all' ? 'filter-btn-active' : ''}`}
            aria-pressed={period === 'all'}
            onClick={() => setPeriod('all')}
          >
            全期間（12ヶ月）
          </button>
          <button
            type="button"
            className={`filter-btn ${period === '6m' ? 'filter-btn-active' : ''}`}
            aria-pressed={period === '6m'}
            onClick={() => setPeriod('6m')}
          >
            直近6ヶ月
          </button>
          <button
            type="button"
            className={`filter-btn ${period === '3m' ? 'filter-btn-active' : ''}`}
            aria-pressed={period === '3m'}
            onClick={() => setPeriod('3m')}
          >
            直近3ヶ月
          </button>
        </div>
      </header>

      {/* サマリーバナー */}
      <div className="summary-banner">
        <div className="summary-item">
          <span className="summary-item-label">選択期間 合計売上</span>
          <div className="summary-item-value">
            ¥{formatCurrency(totals.revenue)}
          </div>
        </div>
        <div className="summary-item">
          <span className="summary-item-label">延べ来客数</span>
          <div className="summary-item-value">
            {formatCount(totals.customers)} 人
          </div>
        </div>
        <div className="summary-item">
          <span className="summary-item-label">期間通算 客単価</span>
          <div className="summary-item-value">
            ¥{formatCurrency(totals.averageSpend)}
          </div>
        </div>
      </div>

      {/* KPIカード一覧 */}
      <div className="kpi-grid">
        {kpiSummaries.map((summary) => (
          <KpiCard key={summary.id} summary={summary} />
        ))}
      </div>

      {/* グラフ推移セクション */}
      <div className="charts-container">
        <ChartSection
          data={filteredData}
          activeMetric={activeMetric}
          onMetricChange={setActiveMetric}
        />
      </div>

      {/* 詳細データテーブル */}
      <div className="table-container">
        <table className="data-table">
          <thead>
            <tr>
              <th className="text-center">月度</th>
              <th className="text-right">売上高</th>
              <th className="text-right">客数</th>
              <th className="text-right">平均客単価</th>
              <th className="text-right">前月比（売上）</th>
            </tr>
          </thead>
          <tbody>
            {filteredData.map((row, index) => {
              const prev = index > 0 ? filteredData[index - 1] : null;
              let diffText = '-';
              let isPos = true;

              if (prev && prev.revenue > 0) {
                const diffRate = ((row.revenue - prev.revenue) / prev.revenue) * 100;
                isPos = diffRate >= 0;
                diffText = `${isPos ? '+' : ''}${diffRate.toFixed(1)}%`;
              }

              return (
                <tr key={`${row.month}-${index}`}>
                  <td className="text-center table-cell-month">{row.month}</td>
                  <td className="text-right">¥{formatCurrency(row.revenue)}</td>
                  <td className="text-right">{formatCount(row.customers)} 人</td>
                  <td className="text-right">¥{formatCurrency(row.averageSpend)}</td>
                  <td className="text-right">
                    {diffText === '-' ? (
                      <span className="table-cell-empty">-</span>
                    ) : (
                      <span
                        className={`kpi-badge ${isPos ? 'kpi-badge-up' : 'kpi-badge-down'}`}
                      >
                        {diffText}
                      </span>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default App;
